package com.asmj.marketplace.favorite.controller;import com.asmj.marketplace.favorite.model.Favorite;import com.asmj.marketplace.favorite.service.FavoriteService;import com.asmj.marketplace.common.response.ApiResponse;import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/favorites")@RequiredArgsConstructor public class FavoriteController{private final FavoriteService s;@PostMapping("/{postId}")public ApiResponse<Favorite> add(Authentication a,@PathVariable String postId){return ApiResponse.ok("Added",s.add(a.getName(),postId));}@DeleteMapping("/{postId}")public ApiResponse<Void> remove(Authentication a,@PathVariable String postId){s.remove(a.getName(),postId);return ApiResponse.ok("Removed",null);}@GetMapping public ApiResponse<List<Favorite>> mine(Authentication a){return ApiResponse.ok("Favorites",s.mine(a.getName()));}}
